/**
 * REQ-CHAT-VIZ-FILTER — shared chat → visualization filter state.
 * Opt-in: filterEnabled default false; chat never filters when off.
 */
export type ChatVizFilterState = {
  filterEnabled: boolean
  chatQuery: string
  appliedQuery: string
}

export function createInitialChatVizFilter(): ChatVizFilterState {
  return { filterEnabled: false, chatQuery: '', appliedQuery: '' }
}

export function setFilterEnabled(
  state: ChatVizFilterState,
  on: boolean,
): ChatVizFilterState {
  return {
    filterEnabled: on,
    chatQuery: state.chatQuery,
    appliedQuery: on ? state.appliedQuery : '',
  }
}

export function applyChatQuery(
  state: ChatVizFilterState,
  q: string,
): ChatVizFilterState {
  const chatQuery = q
  const appliedQuery = state.filterEnabled ? q.trim() : state.appliedQuery
  return {
    filterEnabled: state.filterEnabled,
    chatQuery,
    appliedQuery: state.filterEnabled ? (q.trim() ? q.trim() : '') : '',
  }
}

export function clearAppliedFilter(state: ChatVizFilterState): ChatVizFilterState {
  return { ...state, chatQuery: '', appliedQuery: '' }
}

/** Match helper for tables/graphs/flow labels */
export function matchesChatVizFilter(
  text: string,
  state: ChatVizFilterState,
): boolean {
  if (!state.filterEnabled) return true
  const q = state.appliedQuery.trim().toLowerCase()
  if (!q) return true
  return text.toLowerCase().includes(q)
}


