import {
  applyChatQuery,
  createInitialChatVizFilter,
  matchesChatVizFilter,
  setFilterEnabled,
} from '../chat-viz-filter'

describe('chat-viz-filter', () => {
  it('defaults to filter disabled', () => {
    const s = createInitialChatVizFilter()
    expect(s.filterEnabled).toBe(false)
    expect(matchesChatVizFilter('anything', s)).toBe(true)
  })

  it('does not apply chat when disabled', () => {
    let s = createInitialChatVizFilter()
    s = applyChatQuery(s, 'foo')
    expect(s.appliedQuery).toBe('')
    expect(matchesChatVizFilter('foo', s)).toBe(true)
  })

  it('applies chat when enabled', () => {
    let s = setFilterEnabled(createInitialChatVizFilter(), true)
    s = applyChatQuery(s, 'bar')
    expect(s.appliedQuery).toBe('bar')
    expect(matchesChatVizFilter('xx bar yy', s)).toBe(true)
    expect(matchesChatVizFilter('zzz', s)).toBe(false)
  })
})


